package jobapi

// The compact service lane is explicit. Its authority is generated by this Go
// process, never decoded from a Worker/public HTTP request or restored on boot.
import (
	"bytes"
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"reflect"
	"strings"
	"sync"
	"time"

	"github.com/TonyP4N/cpagx-go/internal/capacity"
	"github.com/TonyP4N/cpagx-go/internal/jobs"
)

var ErrVerificationPending = errors.New("compact source verification pending")

const SharedStorageBudget = "shared-storage-budget-2"

type compactApproval struct {
	approval json.RawMessage
	err      error
	pending  bool
}
type compactAuthority struct {
	mu          sync.Mutex
	key         [32]byte
	initialized bool
	entries     map[string]*compactApproval
}

var compactVerifySlot = make(chan struct{}, 1)

func IsCompactPayload(p Payload) bool {
	return p.CapacityProfile == capacity.EngineeringCore && p.StorageFormat == capacity.CoreSharedFormat && p.ResourceProfile == capacity.StorageBudget && p.StorageBudgetVersion == SharedStorageBudget
}
func compactArtifactNames(p Payload) []string {
	names := []string{"run_manifest.json", "shared/manifest.json", "shared/shared.sqlite3", "sources/profile.json", "sources/process.csv"}
	refs, _ := p.networkRefs()
	for i := range refs {
		names = append(names, networkSourceName(i))
	}
	return names
}
func (s *Server) compactInventory(base string, p Payload, sha string) error {
	root, err := s.file(strings.TrimSuffix(base, "/"))
	if err != nil {
		return err
	}
	expected := map[string]bool{"manifest.json": true}
	for _, n := range compactArtifactNames(p) {
		expected[n] = true
	}
	if sha != "" {
		expected[sha+".json"] = true
	}
	found := map[string]bool{}
	err = filepath.WalkDir(root, func(path string, e os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if path == root {
			return nil
		}
		rel, _ := filepath.Rel(root, path)
		rel = filepath.ToSlash(rel)
		if e.Type()&os.ModeSymlink != 0 {
			return errors.New("compact symlink forbidden")
		}
		if e.IsDir() {
			if rel != "shared" && rel != "sources" {
				return errors.New("unexpected compact directory")
			}
			return nil
		}
		info, err := e.Info()
		if err != nil || !info.Mode().IsRegular() || !expected[rel] {
			return errors.New("unexpected compact physical artifact")
		}
		found[rel] = true
		return nil
	})
	if err != nil {
		return err
	}
	for n := range expected {
		if n == sha+".json" {
			continue
		}
		if !found[n] {
			return errors.New("missing compact physical artifact: " + n)
		}
	}
	return nil
}
func (s *Server) compactWrapper(ctx context.Context, base string, p Payload, sha string) (m Manifest, err error) {
	defer func() {
		if err != nil {
			err = fmt.Errorf("%w: %w", ErrCompactResultChanged, err)
		}
	}()
	if !IsCompactPayload(p) || !shaPattern.MatchString(sha) {
		return m, errors.New("invalid compact execution binding")
	}
	path, err := s.file(base + "manifest.json")
	if err != nil {
		return m, err
	}
	raw, err := readFileBounded(path, 65536)
	if err != nil || bytesSHA(raw) != sha {
		return m, errors.New("compact publication wrapper changed")
	}
	d := json.NewDecoder(bytes.NewReader(raw))
	d.DisallowUnknownFields()
	if d.Decode(&m) != nil || d.Decode(new(any)) != io.EOF {
		return m, errors.New("invalid compact wrapper")
	}
	if m.RunID == "" || m.AttemptID < 1 || m.CapacityProfile != p.CapacityProfile || m.ResourceProfile != p.ResourceProfile || m.Fingerprint != p.Fingerprint || m.StorageFormat != p.StorageFormat || m.StorageBudgetVersion != p.StorageBudgetVersion || m.ReplayVersion != p.ReplayVersion || m.HistoryFormat != p.HistoryFormat || !publicationInputsMatch(p, m.Inputs, m.Networks) {
		return m, errors.New("compact wrapper context mismatch")
	}
	expected := map[string]bool{}
	for _, n := range compactArtifactNames(p) {
		expected[n] = true
	}
	var total int64
	if len(m.Artifacts) != len(expected) {
		return m, errors.New("compact inventory count mismatch")
	}
	for _, a := range m.Artifacts {
		if !expected[a.Path] || !shaPattern.MatchString(a.SHA) {
			return m, errors.New("compact inventory invalid")
		}
		delete(expected, a.Path)
		bound := int64(1 << 30)
		if strings.HasSuffix(a.Path, "manifest.json") {
			bound = 65536
		}
		path, err = s.file(base + a.Path)
		if err != nil {
			return m, err
		}
		if err = snapshotHashFile(ctx, path, a.SHA, a.Size, bound); err != nil {
			return m, err
		}
		total += a.Size
	}
	if total > 1<<30 {
		return m, errors.New("compact output budget exceeded")
	}
	if err = s.compactInventory(base, p, sha); err != nil {
		return m, err
	}
	// Retained originals are an exact copy of the immutable task sources.
	refs, _ := p.networkRefs()
	for i, ref := range refs {
		if _, err = s.checkBounded(Ref{base + networkSourceName(i), ref.SHA}, 64<<20); err != nil {
			return m, err
		}
	}
	for _, ref := range []Ref{{base + "sources/process.csv", p.Process.SHA}, {base + "sources/profile.json", p.Profile.SHA}} {
		if _, err = s.checkBounded(ref, 8<<20); err != nil {
			return m, err
		}
	}
	var core struct {
		Run       string `json:"run_id"`
		Attempt   int    `json:"attempt_id"`
		Config    string `json:"config_fingerprint"`
		Mode      string `json:"mode"`
		Storage   string `json:"storage_format"`
		Artifacts []struct {
			Path string `json:"path"`
			SHA  string `json:"sha256"`
			Size int64  `json:"size_bytes"`
		} `json:"artifacts"`
	}
	path, err = s.file(base + "run_manifest.json")
	if err != nil {
		return m, err
	}
	raw, err = readFileBounded(path, 65536)
	if err != nil || json.Unmarshal(raw, &core) != nil {
		return m, errors.New("invalid compact core manifest")
	}
	mode := "offline"
	if p.Kind == "dual-source-replay" {
		mode = "replay"
	}
	var id string
	var attempt int
	if _, err = fmt.Sscanf(base, "jobs/%s", &id); err != nil {
		return m, err
	}
	parts := strings.Split(strings.Trim(base, "/"), "/")
	id = parts[1]
	fmt.Sscanf(parts[2], "attempt-%d", &attempt)
	if m.RunID != id || m.AttemptID != attempt || core.Run != id || core.Attempt != attempt || core.Config != p.Fingerprint || core.Mode != mode || core.Storage != p.StorageFormat || len(core.Artifacts) != len(m.Artifacts)-1 {
		return m, errors.New("compact core run/attempt/config binding mismatch")
	}
	for _, a := range core.Artifacts {
		matched := false
		for _, b := range m.Artifacts {
			if a.Path == b.Path && a.SHA == b.SHA && a.Size == b.Size {
				matched = true
			}
		}
		if !matched || a.Path == "run_manifest.json" {
			return m, errors.New("compact core inventory mismatch")
		}
	}
	return m, nil
}
func (s *Server) compactCLI(ctx context.Context, base string, p Payload, sha, action string, approval json.RawMessage, query map[string]any) ([]byte, error) {
	root, err := s.file(strings.TrimSuffix(base, "/"))
	if err != nil {
		return nil, err
	}
	payload, _ := json.Marshal(p)
	payloadSHA, err := DualProfileFingerprint(payload)
	if err != nil {
		return nil, err
	}
	parts := strings.Split(strings.Trim(base, "/"), "/")
	attempt := 0
	fmt.Sscanf(parts[2], "attempt-%d", &attempt)
	binding := map[string]any{"run_id": parts[1], "attempt_id": attempt, "config_fingerprint": p.Fingerprint, "payload_sha256": payloadSHA, "storage_format": p.StorageFormat, "capacity_profile": p.CapacityProfile, "resource_profile": p.ResourceProfile, "storage_budget_version": p.StorageBudgetVersion, "publication_sha256": sha}
	request := map[string]any{"action": action, "output_dir": root, "binding": binding}
	if approval != nil {
		request["approval"] = approval
	}
	if query != nil {
		request["query"] = query
	}
	raw, err := json.Marshal(request)
	if err != nil {
		return nil, err
	}
	s.compact.mu.Lock()
	if !s.compact.initialized {
		if _, err = rand.Read(s.compact.key[:]); err != nil {
			s.compact.mu.Unlock()
			return nil, err
		}
		s.compact.initialized = true
		if s.compact.entries == nil {
			s.compact.entries = map[string]*compactApproval{}
		}
	}
	key := s.compact.key
	s.compact.mu.Unlock()
	if action == "verify" {
		return s.compactDockerVerify(ctx, base, p, sha, request, key)
	}
	rd, wr, err := os.Pipe()
	if err != nil {
		return nil, err
	}
	defer rd.Close()
	if _, err = wr.Write(key[:]); err != nil {
		wr.Close()
		return nil, err
	}
	wr.Close()
	python := s.PythonBin
	if python == "" {
		python = "python3"
	}
	cmd := exec.CommandContext(ctx, python, "-m", "cpag_core.shared_service", "--key-fd", "3")
	cmd.ExtraFiles = []*os.File{rd}
	cmd.Stdin = bytes.NewReader(raw)
	cmd.WaitDelay = time.Second
	pythonPath := s.PythonPath
	if pythonPath == "" {
		pythonPath = filepath.Clean(filepath.Join(dualSchemaDir(), "../services/analysis/src"))
	}
	cmd.Env = append(os.Environ(), "PYTHONPATH="+pythonPath, "PYTHONDONTWRITEBYTECODE=1")
	stdout, stderr := &boundedCLIOutput{maximum: 8 << 20}, &boundedCLIOutput{maximum: 65536}
	cmd.Stdout = stdout
	cmd.Stderr = stderr
	if err = cmd.Run(); err != nil {
		if ctx.Err() != nil {
			return nil, ctx.Err()
		}
		if stdout.exceeded {
			return nil, fmt.Errorf("%w: helper response exceeds 8MiB", ErrCompactQueryLimit)
		}
		return nil, compactHelperError(stderr.Bytes())
	}
	if !json.Valid(stdout.Bytes()) {
		return nil, errors.New("invalid compact helper response")
	}
	return append([]byte(nil), stdout.Bytes()...), nil
}

// The background verifier cannot inherit a short HTTP request deadline. Only
// successful full source reconstruction can create an entry usable by reads.
func (s *Server) compactApprovalFor(base string, p Payload, sha string) (json.RawMessage, error) {
	key := base + sha
	s.compact.mu.Lock()
	if s.compact.entries == nil {
		s.compact.entries = map[string]*compactApproval{}
	}
	if e := s.compact.entries[key]; e != nil {
		approval, err, pending := append(json.RawMessage(nil), e.approval...), e.err, e.pending
		s.compact.mu.Unlock()
		if pending {
			return nil, ErrVerificationPending
		}
		return approval, err
	}
	if len(s.compact.entries) >= 16 {
		for existing, state := range s.compact.entries {
			if !state.pending {
				delete(s.compact.entries, existing)
				break
			}
		}
	}
	if len(s.compact.entries) >= 16 {
		s.compact.mu.Unlock()
		return nil, errors.New("compact verifier state capacity reached")
	}
	e := &compactApproval{pending: true}
	s.compact.entries[key] = e
	s.compact.mu.Unlock()
	go func() {
		ctx, cancel := context.WithTimeout(context.Background(), 1800*time.Second)
		defer cancel()
		select {
		case compactVerifySlot <- struct{}{}:
			defer func() { <-compactVerifySlot }()
		case <-ctx.Done():
			s.compact.mu.Lock()
			e.pending = false
			e.err = ctx.Err()
			s.compact.mu.Unlock()
			return
		}
		_, err := s.compactWrapper(ctx, base, p, sha)
		var raw []byte
		if err == nil {
			raw, err = s.compactCLI(ctx, base, p, sha, "verify", nil, nil)
		}
		var result struct {
			Approval json.RawMessage `json:"approval"`
		}
		if err == nil && (json.Unmarshal(raw, &result) != nil || len(result.Approval) == 0) {
			err = errors.New("compact verifier omitted service approval")
		}
		if err == nil {
			_, err = s.compactWrapper(ctx, base, p, sha)
		}
		s.compact.mu.Lock()
		e.pending = false
		e.err = err
		if err == nil {
			e.approval = result.Approval
		}
		s.compact.mu.Unlock()
	}()
	return nil, ErrVerificationPending
}
func (s *Server) compactPublished(r *http.Request, id string) (string, Payload, Manifest, json.RawMessage, error) {
	st, err := s.Repo.Status(r.Context(), id)
	var p Payload
	var m Manifest
	if err != nil {
		return "", p, m, nil, err
	}
	if json.Unmarshal(st.Payload, &p) != nil || !IsCompactPayload(p) || st.State != "succeeded" || st.ArtifactSHA256 == nil || st.ArtifactPath == nil {
		return "", p, m, nil, errors.New("verified compact publication unavailable")
	}
	base := replayBase(id, st.Attempt)
	if *st.ArtifactPath != base+*st.ArtifactSHA256+".json" {
		return "", p, m, nil, fmt.Errorf("%w: published attempt mismatch", ErrCompactResultChanged)
	}
	if err = s.validHistoricalPayload(p); err != nil {
		return "", p, m, nil, fmt.Errorf("%w: %w", ErrCompactResultChanged, err)
	}
	m, err = s.compactWrapper(r.Context(), base, p, *st.ArtifactSHA256)
	if err != nil {
		return "", p, m, nil, err
	}
	if _, err = s.check(Ref{*st.ArtifactPath, *st.ArtifactSHA256}); err != nil {
		return "", p, m, nil, fmt.Errorf("%w: %w", ErrCompactResultChanged, err)
	}
	approval, err := s.compactApprovalFor(base, p, *st.ArtifactSHA256)
	return base, p, m, approval, err
}
func (s *Server) VerifiedCompactQuery(r *http.Request, id, action string, query map[string]any) ([]byte, error) {
	ctx, cancel := context.WithTimeout(r.Context(), 10*time.Second)
	defer cancel()
	r = r.WithContext(ctx)
	base, p, _, approval, err := s.compactPublished(r, id)
	if err != nil {
		return nil, err
	}
	st, err := s.Repo.Status(r.Context(), id)
	if err != nil {
		return nil, err
	}
	q := map[string]any{}
	for k, v := range query {
		q[k] = v
	}
	q["action"] = action
	raw, err := s.compactCLI(ctx, base, p, *st.ArtifactSHA256, "query", approval, q)
	if err != nil {
		return nil, err
	}
	after, err := s.Repo.Status(r.Context(), id)
	if err != nil || after.State != "succeeded" || after.Attempt != st.Attempt || !reflect.DeepEqual(after.ArtifactSHA256, st.ArtifactSHA256) || !bytes.Equal(after.Payload, st.Payload) {
		return nil, fmt.Errorf("%w: publication changed during query", ErrCompactResultChanged)
	}
	return raw, nil
}
func (s *Server) isCompactRun(r *http.Request, id string) bool {
	st, err := s.Repo.Status(r.Context(), id)
	if err != nil {
		return false
	}
	var p Payload
	return json.Unmarshal(st.Payload, &p) == nil && IsCompactPayload(p)
}
func (s *Server) serveCompactQuery(w http.ResponseWriter, r *http.Request, id string) error {
	q := r.URL.Query()
	action := q.Get("action")
	if action == "" {
		action = "metadata"
	}
	allowed := map[string]bool{"metadata": true, "page": true, "get": true, "graph": true, "snapshot": true, "revisions": true, "selection": true, "evidence": true}
	if !allowed[action] {
		return fmt.Errorf("%w: unsupported public query", ErrCompactQueryLimit)
	}
	query := map[string]any{}
	for _, name := range []string{"logical_root", "operation", "change"} {
		if q.Has(name) {
			query[name] = q.Get(name)
		}
	}
	if q.Has("path") {
		var path []any
		if len(q.Get("path")) > 8192 || json.Unmarshal([]byte(q.Get("path")), &path) != nil || len(path) > 32 {
			return fmt.Errorf("%w: invalid bounded path", ErrCompactQueryLimit)
		}
		query["path"] = path
	}
	for _, spec := range []struct {
		name          string
		def, min, max int
	}{{"offset", 0, 0, 1000000}, {"limit", 100, 1, 100}, {"snapshot", 0, 0, 64999}, {"after", 0, 0, 90000}, {"ref_offset", 0, 0, 1000000}, {"ref_limit", 100, 1, 100}} {
		if q.Has(spec.name) {
			n, err := replayQueryInt(r, spec.name, spec.def, spec.min, spec.max)
			if err != nil {
				return fmt.Errorf("%w: %v", ErrCompactQueryLimit, err)
			}
			query[spec.name] = n
		}
	}
	if q.Has("trigger") {
		if q.Get("trigger") != "true" {
			return fmt.Errorf("%w: invalid trigger", ErrCompactQueryLimit)
		}
		query["trigger"] = true
	}
	raw, err := s.VerifiedCompactQuery(r, id, action, query)
	if err != nil {
		return err
	}
	w.Header().Set("Content-Type", "application/json")
	_, err = w.Write(raw)
	return err
}
func (s *Server) completeCompact(r *http.Request, c jobs.Claim, p Payload, sha string, done bool) error {
	base := replayBase(c.ID, c.Attempt)
	if _, err := s.compactWrapper(r.Context(), base, p, sha); err != nil {
		return err
	}
	if _, err := s.compactApprovalFor(base, p, sha); err != nil {
		return err
	}
	key, err := jobs.ArtifactKey(c, sha)
	if err != nil {
		return err
	}
	if done {
		_, err = s.check(Ref{key, sha})
		return err
	}
	if err = s.Repo.CheckPublication(r.Context(), c); err != nil {
		return err
	}
	raw, err := os.ReadFile(filepath.Join(s.Root, base, "manifest.json"))
	if err != nil || bytesSHA(raw) != sha {
		return errors.New("compact wrapper changed before publication")
	}
	out, err := os.OpenFile(filepath.Join(s.Root, key), os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0400)
	if os.IsExist(err) {
		if _, err = s.check(Ref{key, sha}); err != nil {
			return err
		}
		return s.Repo.Complete(r.Context(), c, key, sha)
	}
	if err != nil {
		return err
	}
	_, err = out.Write(raw)
	if err == nil {
		err = out.Sync()
	}
	closeErr := out.Close()
	if err != nil {
		return err
	}
	if closeErr != nil {
		return closeErr
	}
	return s.Repo.Complete(r.Context(), c, key, sha)
}

func (s *Server) IsCompactRun(r *http.Request, id string) (bool, error) {
	st, err := s.Repo.Status(r.Context(), id)
	if err != nil {
		return false, err
	}
	var p Payload
	if err = json.Unmarshal(st.Payload, &p); err != nil {
		return false, err
	}
	return IsCompactPayload(p), nil
}
func (s *Server) OpenVerifiedCompactArtifact(r *http.Request, id, name string) (*os.File, error) {
	// A bounded metadata read verifies the service capability and exact current
	// bytes, including all original sources, before any download is exposed.
	if _, err := s.VerifiedCompactQuery(r, id, "metadata", nil); err != nil {
		return nil, err
	}
	base, p, m, _, err := s.compactPublished(r, id)
	if err != nil {
		return nil, err
	}
	for _, a := range m.Artifacts {
		if a.Path != name {
			continue
		}
		path, err := s.file(base + name)
		if err != nil {
			return nil, err
		}
		f, err := os.Open(path)
		if err != nil {
			return nil, err
		}
		limit, _ := s.artifactLimit(p)
		info, err := f.Stat()
		if err != nil || !info.Mode().IsRegular() || info.Size() != a.Size || a.Size > limit {
			f.Close()
			return nil, errors.New("compact download size changed")
		}
		// Copy into an unlinked private descriptor while hashing. Serving this
		// snapshot cannot expose a later rewrite of the producer's inode.
		scratch, err := os.CreateTemp(s.ControlRoot, "compact-download-")
		if err != nil {
			f.Close()
			return nil, err
		}
		os.Remove(scratch.Name())
		hash := sha256.New()
		buffer := make([]byte, 64<<10)
		var copied int64
		for {
			if err = r.Context().Err(); err != nil {
				break
			}
			var n int
			n, err = f.Read(buffer)
			if n > 0 {
				copied += int64(n)
				if copied > a.Size {
					err = errors.New("compact download grew")
					break
				}
				if _, e := scratch.Write(buffer[:n]); e != nil {
					err = e
					break
				}
				hash.Write(buffer[:n])
			}
			if err == io.EOF {
				err = nil
				break
			}
			if err != nil {
				break
			}
		}
		f.Close()
		if err != nil || copied != a.Size || fmt.Sprintf("%x", hash.Sum(nil)) != a.SHA {
			scratch.Close()
			return nil, errors.New("compact download bytes changed or deadline exceeded")
		}
		if _, err = scratch.Seek(0, io.SeekStart); err != nil {
			scratch.Close()
			return nil, err
		}
		return scratch, nil
	}
	return nil, errors.New("compact artifact not found")
}
